import json, os, glob
for n, lim in ((561, 2500), (564, 5000), (566, 5000), (567, 9000)):
    d = '.session/history/sessions/%d' % n
    fs = sorted(glob.glob(d + '/**', recursive=True))
    print('=== session', n, [(f[len(d)+1:], os.path.getsize(f)) for f in fs if os.path.isfile(f)])
    for f in fs:
        if not os.path.isfile(f) or os.path.basename(f) == 'task.md':
            continue
        t = open(f, encoding='utf-8', errors='replace').read()
        if f.endswith('.json'):
            try:
                j = json.loads(t)
                if isinstance(j, dict):
                    print('--', f, 'keys', list(j.keys()))
                    for k in ('report', 'text', 'body', 'content'):
                        if isinstance(j.get(k), str):
                            t = j[k]
                            break
            except Exception as e:
                print('json error', e)
        print('--', f)
        print(t[:lim])
"

