import json, subprocess
def git(*a):
    p = subprocess.run(('git',) + a, capture_output=True, text=True)
    return p.returncode, p.stdout, p.stderr
rc, out, err = git('log', '-3', '--format=%H %cI %s', 'origin/loop-runtime')
print('log', rc, out[:600], err[:300])
rc, out, err = git('ls-tree', '--name-only', 'origin/loop-runtime')
print('tree', rc, out[:800], err[:300])
def short(v, n=700):
    s = v if isinstance(v, str) else json.dumps(v, ensure_ascii=False)
    return s[:n]
for n in (564, 567):
    rc, out, err = git('show', 'origin/loop-runtime:sessions/%d.json' % n)
    print('=== sessions/%d.json' % n, rc, len(out), err[:300])
    if rc:
        continue
    try:
        j = json.loads(out)
    except Exception as e:
        print('json error', e, out[:1500])
        continue
    if isinstance(j, dict):
        print('keys', list(j.keys()))
        for k, v in j.items():
            if isinstance(v, list):
                print(' ', k, 'list', len(v))
                for item in v[-16:]:
                    print('    ', short(item, 420))
            else:
                print(' ', k, ':', short(v))
    else:
        print(short(j, 3000))
rc, out, err = git('show', 'origin/loop-runtime:pool.json')
print('=== pool.json', rc, len(out), err[:300])
print(out[:3500])
"

